{
  "anomaly_detected": true,
  "confidence": 0.92,
  "anomalies": [
    {
      "category": "open_connection",
      "components": ["FCC1", "NAVC1", "REG2"],
      "pins": [
        "FCC1.11",
        "FCC1.27",
        "FCC1.50",
        "FCC1.75",
        "FCC1.100",
        "NAVC1.19",
        "NAVC1.32",
        "NAVC1.48",
        "NAVC1.64",
        "REG2.1"
      ],
      "nets": [
        "+3V3",
        "+3.3V",
        "unconnected-(FCC1-VDD-Pad11)",
        "unconnected-(NAVC1-VDD-Pad19)"
      ],
      "observed": "The net named +3V3 contains MCU decoupling capacitors, pull-up resistors, connectors and U11, but no regulator output or MCU VDD pin. The STM32 VDD pins are explicitly placed on unconnected nets, while REG2's OUT pin is connected to +3.3V, not +3V3.",
      "expected": "The LD39200 3.3 V output should drive the MCU 3V3 rail and connect to the VDD pins of both FCC1 and NAVC1, as stated in the power section of the specification.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(net (code \"2\") (name \"+3V3\") (class \"Default\")"
        },
        {
          "source": "netlist",
          "quote": "(net (code \"217\") (name \"unconnected-(FCC1-VDD-Pad11)\") (class \"Default\")"
        },
        {
          "source": "netlist",
          "quote": "(node (ref \"REG2\") (pin \"1\") (pinfunction \"OUT\") (pintype \"unspecified\"))"
        },
        {
          "source": "spec",
          "quote": "3V3 feeds both MCUs (FCC, NAVC) and all I2C sensor ICs"
        }
      ],
      "impact": "Both MCUs and the MCU-side pull-up/decoupling network are unpowered from the schematic connectivity, so the flight controller cannot boot or operate normally.",
      "confidence": 0.95
    },
    {
      "category": "bridged_nets",
      "components": ["FCC1", "UART3_FCC1"],
      "pins": ["FCC1.48", "FCC1.73", "UART3_FCC1.3", "UART3_FCC1.4"],
      "nets": ["UART3_TX_FCC", "UART3_RX_FCC"],
      "observed": "FCC1 pins 48 and 73, whose symbol pin functions are VCAP, are connected to UART3_TX_FCC and UART3_RX_FCC. Those same nets also connect to the UART3_FCC1 connector.",
      "expected": "VCAP pins are internal regulator decoupling pins and should be bypassed to ground; they should not be merged with external UART signal nets.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(net (code \"147\") (name \"UART3_TX_FCC\") (class \"Default\")"
        },
        {
          "source": "netlist",
          "quote": "(node (ref \"FCC1\") (pin \"48\") (pinfunction \"VCAP\") (pintype \"power_out\"))"
        },
        {
          "source": "netlist",
          "quote": "(pin (num \"48\") (name \"VCAP\") (type \"power_out\"))"
        }
      ],
      "impact": "The MCU VCAP decoupling nodes are shorted to UART signals, corrupting the internal supply and making UART3 unusable; this can prevent the MCU from operating or damage it.",
      "confidence": 0.9
    },
    {
      "category": "missing_component",
      "components": ["USB3", "USB4"],
      "pins": ["USB3.2", "USB3.3", "USB4.2", "USB4.3"],
      "nets": [
        "unconnected-(USB3-D+-Pad3)",
        "unconnected-(USB3-D--Pad2)",
        "unconnected-(USB4-D+-Pad3)",
        "unconnected-(USB4-D--Pad2)"
      ],
      "observed": "The netlist contains no CH330 or equivalent USB-UART bridge components, and the USB3/USB4 differential data pins are on unconnected nets.",
      "expected": "The specification states that the Connections sheet contains two otter_CH330 USB-to-UART converters for programming/debug UART-to-USB.",
      "evidence": [
        {
          "source": "spec",
          "quote": "USB-UART bridges (programming/debug) | Connections | otter_CH330 ×2"
        },
        {
          "source": "netlist",
          "quote": "(net (code \"314\") (name \"unconnected-(USB3-D+-Pad3)\") (class \"Default\")"
        }
      ],
      "impact": "The UART-to-USB debug/programming interfaces described in the design are absent, so those USB ports cannot provide serial communication.",
      "confidence": 0.82
    }
  ],
  "summary": "The build deviates materially from the intended Hades design: the 3V3 MCU rail is not driven and MCU VDD/VCAP pins are misconnected, and the specified CH330 USB-UART bridges are missing."
}

